import{_ as t,a0 as r,w as o,s as d,ao as p,I as l,x as a,a1 as i,A as e}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"通过“猜数字”游戏学习 Basic | LCTT x X-CMD","titleTemplate":false,"description":"通过“猜数字”游戏学习 Basic | LCTT (202302) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"通过“猜数字”游戏学习 Basic | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"通过“猜数字”游戏学习 Basic | LCTT (202302) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202302/20230202.1 ⭐️ Learn Basic by coding a game","title":"通过“猜数字”游戏学习 Basic","tag":"202302","desc":""},"relativePath":"202302/20230202.1 ⭐️ Learn Basic by coding a game.md","filePath":"[post].md"}'),u={name:"202302/20230202.1 ⭐️ Learn Basic by coding a game.md"};function g(b,s,h,c,k,m){const n=r("Link");return o(),d("div",null,[s[23]||(s[23]=p('<h1 id="通过-猜数字-游戏学习-basic" tabindex="-1">通过“猜数字”游戏学习 Basic <a class="header-anchor" href="#通过-猜数字-游戏学习-basic" aria-label="Permalink to “通过“猜数字”游戏学习 Basic”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202302/11/103834qsra0ryedbdnrdez.jpg" alt=""></p><blockquote><p>本教程让你通过编写一个 “猜数字” 游戏来探索 Basic。</p></blockquote><p>用多种语言编写同一个应用是学习新的编程语言的好方法。大多数编程语言都有某些共同点，如：</p><ul><li>变量</li><li>表达式</li><li>语句</li></ul><p>这些概念是大多数编程语言的基础。当你理解了它们，你就可以开始研究其他的东西了。</p><p>编程语言通常有一些相似之处。当你了解了一种编程语言，你就可以通过认识其差异来学习另一种语言的基础知识。</p><p>用标准程序进行练习是学习新语言的一个好方法。它使你能够专注于语言，而不是程序的逻辑。在这个系列文章中，我使用了一个“猜数字”的程序，在这个程序中，计算机在 1 到 100 之间挑选一个数字，并要求你猜出来。程序循环进行，直到你猜对数字为止。</p><p>这个程序锻炼了编程语言中的几个概念：</p><ul><li>变量</li><li>输入</li><li>输出</li><li>条件判断</li><li>循环</li></ul><p>这是学习一种新的编程语言的很好的实践。本文主要介绍 Basic。</p><h3 id="在-bywater-basic-中猜数字" tabindex="-1">在（Bywater）Basic 中猜数字 <a class="header-anchor" href="#在-bywater-basic-中猜数字" aria-label="Permalink to “在（Bywater）Basic 中猜数字”">​</a></h3>',12)),l("p",null,[s[1]||(s[1]=a("对于 Basic 编程语言，没有真正的标准。维基百科说：“BASIC（",-1)),s[2]||(s[2]=l("ruby",null,[a("初学者通用符号指令代码"),l("rt",null,"Beginners' All-purpose Symbolic Instruction Code")],-1)),s[3]||(s[3]=a("）是一个通用的高级编程语言系列，旨在方便使用”。",-1)),i(n,{href:"https://yeolpishack.net/repos/ChipMaster/bwBASIC"},{default:e(()=>[...s[0]||(s[0]=[a("BWBasic",-1)])]),_:1}),s[4]||(s[4]=a(" 的实现是在 GPL 下提供的。",-1))]),s[24]||(s[24]=p(`<p>你可以通过编写一个“猜数字”游戏来探索 Basic。</p><h3 id="在-linux-上安装-basic" tabindex="-1">在 Linux 上安装 Basic <a class="header-anchor" href="#在-linux-上安装-basic" aria-label="Permalink to “在 Linux 上安装 Basic”">​</a></h3><p>在 Debian 或 Ubuntu 中，你可以用以下方法安装 Basic：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ apt install -y bwbasic</span></span></code></pre></div><p>下载 Fedora、CentOS、Mageia 和其他任何 Linux 发行版的最新版本 tarball。解压并设置可执行，然后从终端运行它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ tar --extract --file bwbasic*z</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$ chmod +x bywater</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$ ./bywater</span></span></code></pre></div>`,6)),l("p",null,[s[6]||(s[6]=a("在 Windows 上，",-1)),i(n,{href:"https://github.com/nerun/bwbasic/releases"},{default:e(()=>[...s[5]||(s[5]=[a("下载 .exe 版本",-1)])]),_:1}),s[7]||(s[7]=a("。",-1))]),s[25]||(s[25]=p(`<h3 id="basic-代码" tabindex="-1">Basic 代码 <a class="header-anchor" href="#basic-代码" aria-label="Permalink to “Basic 代码”">​</a></h3><p>下面是我的实现：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>10 value$ = cint(rnd * 100) + 1</span></span>
<span class="line"><span>20 input &quot;enter guess&quot;; guess$</span></span>
<span class="line"><span>30 guess$ = val(guess$)</span></span>
<span class="line"><span>40 if guess$ &lt; value$ then print &quot;Too low&quot;</span></span>
<span class="line"><span>50 if guess$ &gt; value$ then print &quot;Too high&quot;</span></span>
<span class="line"><span>60 if guess$ = value$ then 80</span></span>
<span class="line"><span>70 goto 20</span></span>
<span class="line"><span>80 print &quot;That&#39;s right&quot;</span></span></code></pre></div><p>Basic 程序可以是编号的，也可以是不编号的。通常情况下，写程序时最好不编号，但用编号的行来写，可以更容易地引用各个行。</p><p>按照惯例，编码者将行写成 10 的倍数。这种方法允许在现有的行之间插入新的行，以便进行调试。下面是我对上述方法的解释：</p><ul><li>10 行：使用内置的 <code>rnd</code> 函数计算一个 1 到 100 之间的随机值，该函数生成一个 0 到 1 之间的数字，不包括 1。</li><li>20 行：询问一个猜测，并将该值放入 <code>guess$</code> 标量变量。30 行将该值转换为一个数字。</li><li>40 行和 50 行：根据比较结果，给猜测者以反馈。</li><li>70 行：回到循环的起点。</li><li>60 行：通过将控制权转移到 80 行来打破循环。80 行是最后一行，所以程序在这之后退出。</li></ul><h3 id="输出示例" tabindex="-1">输出示例 <a class="header-anchor" href="#输出示例" aria-label="Permalink to “输出示例”">​</a></h3><p>下面是将该程序放入 <code>program.bas</code> 后的一个例子：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ bwbasic program.bas</span></span>
<span class="line"><span>Bywater BASIC Interpreter/Shell, version 2.20 patch level 2</span></span>
<span class="line"><span>Copyright (c) 1993, Ted A. Campbell</span></span>
<span class="line"><span>Copyright (c) 1995-1997, Jon B. Volkoff</span></span>
<span class="line"><span></span></span>
<span class="line"><span>enter guess? 50</span></span>
<span class="line"><span>Too low</span></span>
<span class="line"><span>enter guess? 75</span></span>
<span class="line"><span>Too low</span></span>
<span class="line"><span>enter guess? 88</span></span>
<span class="line"><span>Too high</span></span>
<span class="line"><span>enter guess? 80</span></span>
<span class="line"><span>Too low</span></span>
<span class="line"><span>enter guess? 84</span></span>
<span class="line"><span>Too low</span></span>
<span class="line"><span>enter guess? 86</span></span>
<span class="line"><span>Too high</span></span>
<span class="line"><span>enter guess? 85</span></span>
<span class="line"><span>That&#39;s right</span></span></code></pre></div><h3 id="开始学习" tabindex="-1">开始学习 <a class="header-anchor" href="#开始学习" aria-label="Permalink to “开始学习”">​</a></h3><p>这个“猜数字”游戏是学习新的编程语言的一个很好的入门程序，因为它以一种相当直接的方式锻炼了几个常见的编程概念。通过在不同的编程语言中实现这个简单的游戏，你可以展示这些语言的一些核心概念，并比较它们的细节。</p><p>你有喜欢的编程语言吗？你会如何用它来写“猜数字”的游戏？请关注本系列文章，看看你可能感兴趣的其他编程语言的例子吧！</p><hr>`,13)),l("p",null,[s[9]||(s[9]=a("via: ",-1)),i(n,{href:"https://opensource.com/article/23/2/learn-basic-coding-game"},{default:e(()=>[...s[8]||(s[8]=[a("https://opensource.com/article/23/2/learn-basic-coding-game",-1)])]),_:1})]),l("p",null,[s[14]||(s[14]=a("作者：",-1)),i(n,{href:"https://opensource.com/users/moshez"},{default:e(()=>[...s[10]||(s[10]=[a("Moshe Zadka",-1)])]),_:1}),s[15]||(s[15]=a(" 选题：",-1)),i(n,{href:"https://github.com/lkxed"},{default:e(()=>[...s[11]||(s[11]=[a("lkxed",-1)])]),_:1}),s[16]||(s[16]=a(" 译者：",-1)),i(n,{href:"https://github.com/geekpi"},{default:e(()=>[...s[12]||(s[12]=[a("geekpi",-1)])]),_:1}),s[17]||(s[17]=a(" 校对：",-1)),i(n,{href:"https://github.com/wxy"},{default:e(()=>[...s[13]||(s[13]=[a("wxy",-1)])]),_:1})]),l("p",null,[s[20]||(s[20]=a("本文由 ",-1)),i(n,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...s[18]||(s[18]=[a("LCTT",-1)])]),_:1}),s[21]||(s[21]=a(" 原创编译，",-1)),i(n,{href:"https://linux.cn/"},{default:e(()=>[...s[19]||(s[19]=[a("Linux中国",-1)])]),_:1}),s[22]||(s[22]=a(" 荣誉推出",-1))])])}const B=t(u,[["render",g]]);export{C as __pageData,B as default};
